macro_rules! deps {
    () => {
        FnCtxt!();
        ItemKind!();
        TypeckRootCtxt!();
    };
}

macro_rules! typeck_with_inspect {
    () => {
        deps!();
        # [instrument (level = "debug" , skip (tcx , inspector) , ret)] fn typeck_with_inspect < 'tcx > (tcx : TyCtxt < 'tcx > , def_id : LocalDefId , inspector : Option < ObligationInspector < 'tcx > > ,) -> & 'tcx ty :: TypeckResults < 'tcx > { let typeck_root_def_id = tcx . typeck_root_def_id (def_id . to_def_id ()) . expect_local () ; if typeck_root_def_id != def_id { return tcx . typeck (typeck_root_def_id) ; } let id = tcx . local_def_id_to_hir_id (def_id) ; let node = tcx . hir_node (id) ; let span = tcx . def_span (def_id) ; let body_id = node . body_id () . unwrap_or_else (| | { span_bug ! (span , "can't type-check body of {:?}" , def_id) ; }) ; let body = tcx . hir_body (body_id) ; let param_env = tcx . param_env (def_id) ; let root_ctxt = TypeckRootCtxt :: new (tcx , def_id) ; if let Some (inspector) = inspector { root_ctxt . infcx . attach_obligation_inspector (inspector) ; } let mut fcx = FnCtxt :: new (& root_ctxt , param_env , def_id) ; if let hir :: Node :: Item (hir :: Item { kind : hir :: ItemKind :: GlobalAsm { .. } , .. }) = node { let ty = fcx . check_expr (body . value) ; fcx . write_ty (id , ty) ; } else if let Some (hir :: FnSig { header , decl , span : fn_sig_span }) = node . fn_sig () { let fn_sig = if decl . output . is_suggestable_infer_ty () . is_some () { fcx . lowerer () . lower_fn_ty (id , header . safety () , header . abi , decl , None , None) } else { tcx . fn_sig (def_id) . instantiate_identity () } ; check_abi (tcx , id , span , fn_sig . abi ()) ; check_custom_abi (tcx , def_id , fn_sig . skip_binder () , * fn_sig_span) ; loops :: check (tcx , def_id , body) ; let mut fn_sig = tcx . liberate_late_bound_regions (def_id . to_def_id () , fn_sig) ; let arg_span = | idx | decl . inputs . get (idx) . map_or (decl . output . span () , | arg : & hir :: Ty < '_ > | arg . span) ; fn_sig . inputs_and_output = tcx . mk_type_list_from_iter (fn_sig . inputs_and_output . iter () . enumerate () . map (| (idx , ty) | fcx . normalize (arg_span (idx) , ty)) ,) ; if tcx . codegen_fn_attrs (def_id) . flags . contains (CodegenFnAttrFlags :: NAKED) { naked_functions :: typeck_naked_fn (tcx , def_id , body) ; } check_fn (& mut fcx , fn_sig , None , decl , def_id , body , tcx . features () . unsized_fn_params ()) ; } else { let expected_type = if let Some (infer_ty) = infer_type_if_missing (& fcx , node) { infer_ty } else if let Some (ty) = node . ty () && ty . is_suggestable_infer_ty () { fcx . lowerer () . lower_ty (ty) } else { tcx . type_of (def_id) . instantiate_identity () } ; loops :: check (tcx , def_id , body) ; let expected_type = fcx . normalize (body . value . span , expected_type) ; let wf_code = ObligationCauseCode :: WellFormed (Some (WellFormedLoc :: Ty (def_id))) ; fcx . register_wf_obligation (expected_type . into () , body . value . span , wf_code) ; fcx . check_expr_coercible_to_type (body . value , expected_type , None) ; fcx . write_ty (id , expected_type) ; } ; fcx . check_repeat_exprs () ; fcx . type_inference_fallback () ; fcx . check_casts () ; fcx . select_obligations_where_possible (| _ | { }) ; fcx . closure_analyze (body) ; assert ! (fcx . deferred_call_resolutions . borrow () . is_empty ()) ; fcx . resolve_rvalue_scopes (def_id . to_def_id ()) ; for (ty , span , code) in fcx . deferred_sized_obligations . borrow_mut () . drain (..) { let ty = fcx . normalize (span , ty) ; fcx . require_type_is_sized (ty , span , code) ; } fcx . select_obligations_where_possible (| _ | { }) ; debug ! (pending_obligations = ? fcx . fulfillment_cx . borrow () . pending_obligations ()) ; fcx . resolve_coroutine_interiors () ; debug ! (pending_obligations = ? fcx . fulfillment_cx . borrow () . pending_obligations ()) ; if fcx . next_trait_solver () { fcx . handle_opaque_type_uses_next () ; } fcx . select_obligations_where_possible (| _ | { }) ; if let None = fcx . infcx . tainted_by_errors () { fcx . report_ambiguity_errors () ; } fcx . check_asms () ; let typeck_results = fcx . resolve_type_vars_in_body (body) ; fcx . detect_opaque_types_added_during_writeback () ; assert_eq ! (typeck_results . hir_owner , id . owner) ; typeck_results }
    };
}

typeck_with_inspect!()